-- Generated from the live inventory and independently reviewed proposals.
-- This migration deliberately applies only the 591 approved assignments. The 42
-- rows requiring review and 19 excluded non-products are absent from this file.
-- Exact normalized-name matches only. Existing taxonomy and original receipt values
-- are preserved: non-null taxonomy snapshots and manually supplied metadata win.
begin;

on conflict (id) do nothing;

on conflict (id) do nothing;

create temporary table taxonomy_assignment (
  normalized_name text primary key,
  family_id text not null references public.product_families(id),
  variant_id text,
  brand text,
  is_organic boolean,
  foreign key (variant_id, family_id) references public.product_variants(id, family_id)
) on commit drop;


do $$
begin
  if (select count(*) from taxonomy_assignment) <> 591 then
    raise exception 'Expected 591 approved taxonomy assignments, found %',
      (select count(*) from taxonomy_assignment);
  end if;
end;
$$;

-- Product fields represent the reusable catalogue identity.
update public.products p
set product_family_id = a.family_id,
    product_variant_id = a.variant_id
from taxonomy_assignment a
where lower(regexp_replace(btrim(p.name), '\s+', ' ', 'g')) = a.normalized_name
  and p.product_family_id is null
  and p.product_variant_id is null;

-- Brand and Bio are independent attributes: filling a missing value never overwrites a manual one.
update public.products p
set brand = coalesce(p.brand, a.brand),
    is_organic = coalesce(p.is_organic, a.is_organic)
from taxonomy_assignment a
where lower(regexp_replace(btrim(p.name), '\s+', ' ', 'g')) = a.normalized_name
  and ((p.brand is null and a.brand is not null)
    or (p.is_organic is null and a.is_organic is not null));

-- Items retain a purchase-time snapshot, including rows not linked to a product.
update public.items i
set product_family_id = a.family_id,
    product_variant_id = a.variant_id
from taxonomy_assignment a
where lower(regexp_replace(btrim(i.product_name), '\s+', ' ', 'g')) = a.normalized_name
  and i.product_family_id is null
  and i.product_variant_id is null;

commit;
